import java.util.*;
import java.io.*;

public class Vaibhav {
    static boolean[] prime;
    static class Pair implements Comparable<Pair> {
        int a, b;
        Pair(int a, int b) { this.a=a; this.b=b; }
        public int compareTo(Pair o) { return this.a - o.a; }
    }
    static long power(long base, long exp, long modVal) {
        long result=1;
        base %= modVal;
        while (exp > 0) {
            if ((exp & 1)==1) result=(result*base)%modVal;
            exp>>=1;
            base=(base*base)%modVal;
        }
        return result;
    }
    static void sortArray(long[] array) {
        List<Long> list=new ArrayList<>();
        for (long val: array) list.add(val);
        Collections.sort(list);
        for (int i=0; i<array.length; i++) array[i]=list.get(i);
    }
    static class FastScanner {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer("");
        String next() {
            while (!st.hasMoreTokens()) {
                try { st=new StringTokenizer(br.readLine()); } catch (IOException e) { e.printStackTrace(); }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        int[] readArray(int n) {
            int[] a=new int[n];
            for (int i=0; i<n; i++) a[i]=nextInt();
            return a;
        }
        long[] readLongArray(int n) {
            long[] a=new long[n];
            for (int i=0; i<n; i++) a[i]=nextLong();
            return a;
        }
    }
    static void sieveOfEratosthenes(int n) {
        prime=new boolean[n+1];
        Arrays.fill(prime, true);
        for (int p=2; p*p<=n; p++) {
            if (prime[p]) {
                for (int i=p*p; i<=n; i+=p) prime[i]=false;
            }
        }
    }
    public static int log2(int x) {
        return (int)(Math.log(x)/Math.log(2));
    }
    static long binomialCoeff(long n, long r) {
        if (r>n) return 0;
        long m=1000000007L;
        long[] inv=new long[(int)r+1];
        inv[0]=1;
        if (r+1>=2) inv[1]=1;
        for (int i=2; i<=r; i++) {
            inv[i]=m - (m/i)*inv[(int)(m%i)]%m;
        }
        long ans=1;
        for (int i=2; i<=r; i++) {
            ans=(ans*inv[i])%m;
        }
        for (long i=n; i>=n-r+1; i--) {
            ans=(ans*i)%m;
        }
        return ans;
    }
    public static long gcd(long a, long b) {
        while (b != 0) {
            long t=b;
            b=a%b;
            a=t;
        }
        return a;
    }
    static long[] facts=new long[300000];
    static long mod=1_000_000_007;
    static long multiply(long a, long b) { return (a*b)%mod; }
    static long addMod(long a, long b) { return (a+b)%mod; }
    static BigInteger bi(String str) { return new BigInteger(str); }
    static FastScanner fs=new FastScanner();
    public static void main(String[] args) {
        int t=1;
        while (t-- > 0) {
            String s=fs.next();
            int len=s.length();
            int max=(int)Math.pow(10,len)-1;
            int min=(int)Math.pow(10,len-1);
            if (min==1) min--;
            if (s.charAt(0)=='0' && s.length()>1) {
                System.out.println("0");
                continue;
            }
            long ans=0;
            for (int i=min; i<=max; i++) {
                if (i%25==0 && can(i, s)) ans++;
            }
            System.out.println(ans);
        }
    }
    public static boolean can(int v, String s) {
        String ss=Integer.toString(v);
        char king='?';
        for (int i=0; i<ss.length(); i++) {
            char c=s.charAt(i);
            if (c!='_' && c!='X') {
                if (c!=ss.charAt(i)) return false;
            } else if (c=='_') {
                continue;
            } else if (c=='X') {
                if (king!='?' && ss.charAt(i)!=king) return false;
                if (king=='?') king=ss.charAt(i);
            }
        }
        return true;
    }
}
